exa = Exa(api_key=os.getenv("EXA_API_KEY"))
parallel = Parallel(api_key=os.getenv("PARALLEL_API_KEY"))
supermemory = SupermemoryClient(api_key=os.getenv("SUPERMEMORY_API_KEY"))
dragonfly_client = dragonfly.Client(url=os.getenv("DRAGONFLY_URL"))

tools_defs = [
    {
        "type": "function",
        "function": {
            "name": "web_search",
            "description": "Search on the web",
            "parameters": {
                "type": "object",
                "properties": {"query": {"type": "string"}},
                "required": ["query"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "code_execution",
            "description": "Code execution in Python",
            "parameters": {
                "type": "object",
                "properties": {"code": {"type": "string"}},
                "required": ["code"]
            }
        }
    }
]

class ResearchSession:
    def __init__(self, session_id: str, goal: str, attachments: List[UploadFile]):
        self.session_id = session_id
        self.goal = goal
        self.attachments = attachments
        self.progress = 0
        self.logs = []
        self.thinking = ""
        self.total_sources = 0
        self.status = "started"
        self.event_emitter = asyncio.Event()
        self.event_queue = asyncio.Queue()

async def evaluate_complexity(query: str) -> tuple:
    response = await xai_client.chat.completions.create(
        model="grok-4-latest",
        messages=[{"role": "system", "content": "Rate the complexity of [query] on a scale of 1-10: 1=simple factual question, 10=PhD-level problem"},
                  {"role": "user", "content": query}],
        temperature=0.1
    )
    complexity = int(response.choices[0].message.content.strip())
    N = min(32, max(5, round(complexity * 2)))
    roles = ['reasoner', 'researcher', 'critic', 'creator', 'validator'] * (N // 5 + 1)
    roles = roles[:N]
    return N, roles

async def run_agent(client, id, role, query, tools):
    messages = [{"role": "system", "content": f"You are Agent #{id}: {role}. Task: {query}. Generate 1-3 hypotheses/calls with tools if necessary. Output strictly JSON: {{'hypotheses': [{{'text': '...', 'confidence': 0-1, 'tools_used': ['tool1']}}], 'self_eval': 'Strengths/weaknesses'}}. Think step by step, prioritize accuracy."},
                {"role": "user", "content": query}]
    response = await client.chat.completions.create(model="grok-4-latest", messages=messages, tools=tools, tool_choice="auto", temperature=0.7)
    return json.loads(response.choices[0].message.content)

async def debate_consensus(client, agents_outputs, tools):
    messages = [{"role": "system", "content": f"Orchestrator: Input: {agents_outputs}. Debate: Rate each hypothesis on a scale of 0-1. Conflict if variance >0.3: iterate with new round max 3x. Consensus: weighted vote, tied majority. Output JSON: {{'best_hypothesis': '...', 'alternatives': [...], 'reliability': avg_confidence}}."},
                {"role": "user", "content": "Run the debate."}]
    response = await client.chat.completions.create(model="grok-4-latest", messages=messages, temperature=0.5)
    return json.loads(response.choices[0].message.content)

async def synthesize(client, consensus, query):
    messages = [{"role": "system", "content": f"Synthesizer: Based on {consensus}, generate user-friendly response: detailed explanation with steps, alternatives, citations, reliability score in %. Maintain style: helpful, witty."},
                {"role": "user", "content": query}]
    response = await client.chat.completions.create(model="grok-4-latest", messages=messages, temperature=0.3)
    return response.choices[0].message.content

async def heavy_query(query: str):
    N, roles = await evaluate_complexity(query)
    tasks = [run_agent(xai_client, i, role, query, tools_defs) for i, role in enumerate(roles)]
    agents_outputs = await asyncio.gather(*tasks)
    consensus = await debate_consensus(xai_client, agents_outputs, tools_defs)
    response = await synthesize(xai_client, consensus, query)
    return response

@app.get("/")
async def serve_frontend():
    with open("index.html", "r") as f:
        return HTMLResponse(content=f.read())

@app.post("/api/chat/stream")
async def chat_stream(message: str = Form(...), files: List[UploadFile] = File(None)):
    async def event_generator():
        yield json.dumps({"type": "start"})
        response = await heavy_query(message)
        for token in response.split():
            yield json.dumps({"type": "token", "content": token + " "})
        yield json.dumps({"type": "done"})
    return StreamingResponse(event_generator(), media_type="text/event-stream")

@app.post("/api/research/start")
async def start_research(goal: str = Form(...), files: List[UploadFile] = File(None)):
    session_id = str(uuid.uuid4())
    session = ResearchSession(session_id, goal, files)
    research_sessions[session_id] = session
    asyncio.create_task(run_research(session))
    return {"session_id": session_id}

async def run_research(session: ResearchSession):
    session.logs.append({"type": "status_update", "phase": "Initialization", "progress": 10})
    session.progress = 10
    exa_results = await exa.search(session.goal, num_results=100, type="fast", contents={"summary": True}, livecrawl="preferred")
    session.total_sources += len(exa_results.results)
    session.logs.append({"type": "exa_complete", "total_sources": session.total_sources})
    session.progress = 50
    consensus = await heavy_query(session.goal)
    session.logs.append({"type": "consensus_computed", "consensus_level": consensus["reliability"]})
    session.progress = 80
    final_report = await synthesize(xai_client, consensus, session.goal)
    session.result = {"final_response": final_report, "total_sources": session.total_sources}
    session.status = "completed"
    session.progress = 100

@app.get("/api/research/{session_id}/events")
async def research_events(session_id: str, request: Request):
    async def event_generator():
        session = research_sessions.get(session_id)
        if not session:
            yield f"data: {json.dumps({'type': 'error', 'message': 'Session not found'})}\n\n"
            return
        while session.status != "completed" and session.status != "error":
            await session.event_emitter.wait()
            while not session.event_queue.empty():
                event = await session.event_queue.get()
                yield f"data: {json.dumps(event)}\n\n"
            session.event_emitter.clear()
        yield f"data: {json.dumps({'type': 'research_complete', 'final_response': session.result['final_response'], 'total_sources': session.result['total_sources']})}\n\n"
    return StreamingResponse(event_generator(), media_type="text/event-stream")

