transition: opacity 0.2s;
}
.attachment-preview-item .remove-btn:hover {
opacity: 1;
}
.mode-indicator {
align-self: flex-start;
font-size: 9px;
font-weight: 600;
text-transform: uppercase;
color: var(--accent-blue);
background: rgba(41, 151, 255, 0.08);
border: 1px solid rgba(41, 151, 255, 0.15);
padding: 4px 10px;
border-radius: 8px;
margin-left: 50px;
opacity: 0;
height: 0;
overflow: hidden;
transition: all 0.4s var(--ease-apple);
letter-spacing: 0.5px;
}
.mode-indicator.visible {
opacity: 1;
height: auto;
margin-bottom: 4px;
}
.input-row-container {
display: flex;
align-items: center;
gap: 12px;
width: 100%;
max-width: 760px;
margin: 0 auto;
}
.icon-button {
width: 38px;
height: 38px;
border-radius: 50%;
background: rgba(255, 255, 255, 0.05);
border: none;
display: flex;
align-items: center;
justify-content: center;
color: var(--text-secondary);
cursor: pointer;
transition: all 0.2s var(--ease-apple);
flex-shrink: 0;
}
.icon-button:hover {
background: rgba(255, 255, 255, 0.1);
color: var(--text-primary);
}
.icon-button:active {
transform: scale(0.94);
}
.icon-button.rotated {
transform: rotate(45deg);
