}
.icon-button.has-attachments {
background: rgba(41, 151, 255, 0.2);
color: var(--accent-blue);
}
.text-input-field {
flex: 1;
background: rgba(255, 255, 255, 0.05);
border: 1px solid transparent;
border-radius: 20px;
height: 40px;
padding: 0 16px;
