}
.send-action-button:not(:disabled):hover {
transform: scale(1.05);
background: #0071e3;
box-shadow: 0 0 15px rgba(41, 151, 255, 0.3);
}
.floating-menu {
position: absolute;
bottom: 80px;
left: 20px;
width: 220px;
background: rgba(10, 10, 10, 0.95);
backdrop-filter: blur(40px) saturate(180%);
-webkit-backdrop-filter: blur(40px) saturate(180%);
border-radius: 16px;
padding: 6px;
border: 1px solid var(--border-subtle);
transform-origin: bottom left;
transform: scale(0.9) translateY(20px);
opacity: 0;
pointer-events: none;
transition: all 0.3s var(--ease-apple);
z-index: 200;
box-shadow: 0 10px 40px rgba(0, 0, 0, 0.7);
}
.floating-menu.visible {
transform: scale(1) translateY(0);
opacity: 1;
pointer-events: auto;
}
.menu-section-label {
font-size: 10px;
font-weight: 500;
color: var(--text-tertiary);
padding: 6px 10px 4px;
text-transform: uppercase;
letter-spacing: 0.5px;
}
.menu-item-button {
display: flex;
align-items: center;
gap: 12px;
width: 100%;
padding: 10px 12px;
background: transparent;
border: none;
border-radius: 10px;
color: var(--text-primary);
font-size: 13px;
font-weight: 400;
text-align: left;
cursor: pointer;
transition: background 0.2s ease;
}
.menu-item-button:hover {
background: rgba(255, 255, 255, 0.08);
}
.menu-item-button svg {
color: var(--accent-blue);
width: 18px;
height: 18px;
}
#overlay-panel {
position: fixed;
top: 0;
left: 0;
width: 100%;
height: 100%;
background: var(--bg-color);
z-index: 300;
display: flex;
flex-direction: column;
transform: translateY(100%);
transition: transform 0.6s var(--ease-apple);
}
#overlay-panel.visible {
transform: translateY(0);
}
.overlay-navigation {
padding: 12px 20px;
padding-top: calc(12px + var(--safe-top));
display: flex;
align-items: center;
justify-content: space-between;
background: rgba(0, 0, 0, 0.5);
backdrop-filter: blur(30px) saturate(180%);
-webkit-backdrop-filter: blur(30px) saturate(180%);
border-bottom: 1px solid var(--border-subtle);
z-index: 10;
}
.overlay-close-button {
background: rgba(255, 255, 255, 0.08);
border: none;
width: 28px;
height: 28px;
border-radius: 50%;
display: flex;
align-items: center;
justify-content: center;
color: var(--text-secondary);
cursor: pointer;
transition: all 0.2s ease;
}
.overlay-close-button:hover {
background: rgba(255, 255, 255, 0.15);
color: var(--text-primary);
}
.overlay-header-title {
font-size: 14px;
font-weight: 500;
max-width: 60%;
white-space: nowrap;
overflow: hidden;
text-overflow: ellipsis;
color: var(--text-primary);
}
.overlay-content-scroll {
flex: 1;
overflow-y: auto;
overflow-x: hidden;
padding: 32px 20px;
padding-bottom: calc(80px + var(--safe-bottom));
-webkit-overflow-scrolling: touch;
overscroll-behavior-y: contain;
}
.result-hero-section {
margin-bottom: 40px;
animation: slideUpFade 0.8s var(--ease-apple) 0.1s forwards;
opacity: 0;
transform: translateY(30px);
}
.status-card {
background: linear-gradient(180deg, #0a0a0a 0%, #000000 100%);
border: 1px solid var(--border-subtle);
border-radius: 22px;
padding: 24px;
display: flex;
align-items: center;
justify-content: space-between;
position: relative;
overflow: hidden;
box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
}
.status-card::before {
content: '';
position: absolute;
top: 0;
right: 0;
width: 60%;
height: 100%;
background: radial-gradient(circle at top right, rgba(41, 151, 255, 0.08) 0%, transparent 70%);
pointer-events: none;
}
.circular-progress-wrapper {
position: relative;
width: 70px;
height: 70px;
}
.progress-ring-svg {
transform: rotate(-90deg);
width: 100%;
height: 100%;
}
.progress-ring-bg {
fill: none;
stroke: rgba(255, 255, 255, 0.08);
stroke-width: 4;
}
.progress-ring-fg {
fill: none;
stroke: var(--accent-blue);
stroke-width: 4;
stroke-linecap: round;
stroke-dasharray: 283;
stroke-dashoffset: 283;
transition: stroke-dashoffset 1.5s var(--ease-apple);
}
.progress-label-value {
position: absolute;
top: 50%;
left: 50%;
transform: translate(-50%, -50%);
font-size: 16px;
font-weight: 500;
font-variant-numeric: tabular-nums;
color: #fff;
letter-spacing: -0.01em;
}
.status-text-content h2 {
font-size: 22px;
font-weight: 500;
margin-bottom: 6px;
color: #fff;
letter-spacing: -0.01em;
}
.status-text-content p {
font-size: 13px;
color: var(--text-secondary);
font-weight: 300;
}
.section-heading {
font-size: 18px;
font-weight: 500;
margin: 40px 0 20px;
color: #fff;
display: flex;
align-items: center;
gap: 10px;
letter-spacing: 0.01em;
}
.thinking-section {
background: rgba(41, 151, 255, 0.05);
border: 1px solid rgba(41, 151, 255, 0.15);
border-radius: 16px;
padding: 20px;
margin: 20px 0;
}
.thinking-section-header {
display: flex;
align-items: center;
gap: 8px;
font-size: 12px;
font-weight: 500;
color: var(--accent-blue);
text-transform: uppercase;
letter-spacing: 0.05em;
margin-bottom: 12px;
}
.thinking-section-content {
font-size: 13px;
color: var(--text-secondary);
line-height: 1.6;
white-space: pre-wrap;
max-height: 200px;
overflow-y: auto;
}
.agent-log-container {
border-left: 1px solid rgba(255, 255, 255, 0.1);
padding-left: 24px;
margin-left: 10px;
}
.log-item {
position: relative;
margin-bottom: 24px;
animation: slideInRight 0.5s var(--ease-apple) forwards;
}
.log-item::after {
content: '';
position: absolute;
left: -28px;
top: 5px;
width: 7px;
height: 7px;
border-radius: 50%;
background: #000;
border: 1px solid var(--text-tertiary);
transition: all 0.4s ease;
}
.log-item.completed::after {
border-color: var(--accent-blue);
background: var(--accent-blue);
box-shadow: 0 0 10px rgba(41, 151, 255, 0.4);
}
.log-content-text {
font-size: 13px;
color: var(--text-secondary);
line-height: 1.5;
letter-spacing: 0.01em;
}
.log-content-text b {
color: var(--text-primary);
font-weight: 400;
}
.markdown-body {
font-size: 15px;
line-height: 1.6;
color: var(--text-primary);
white-space: pre-wrap;
font-weight: 300;
opacity: 0.95;
font-family: -apple-system, BlinkMacSystemFont, sans-serif;
}
#login-modal {
position: fixed;
top: 0;
left: 0;
width: 100%;
height: 100%;
z-index: 2000;
background: rgba(0, 0, 0, 0.7);
backdrop-filter: blur(40px) saturate(180%);
-webkit-backdrop-filter: blur(40px) saturate(180%);
display: flex;
align-items: center;
justify-content: center;
opacity: 1;
transition: opacity 0.6s ease;
}
.login-card {
background: #000000;
border: 1px solid var(--border-subtle);
border-radius: 26px;
padding: 40px 32px;
width: 90%;
max-width: 360px;
text-align: center;
box-shadow: 0 40px 100px rgba(0,0,0,0.8);
transform: scale(1);
transition: transform 0.6s var(--ease-apple);
}
.login-headline {
font-size: 28px;
font-weight: 500;
margin-bottom: 10px;
color: #fff;
letter-spacing: -0.01em;
}
.login-subtext {
font-size: 15px;
color: var(--text-secondary);
margin-bottom: 32px;
line-height: 1.4;
font-weight: 300;
}
.primary-button {
background: var(--accent-blue);
color: #fff;
border: none;
padding: 14px 28px;
font-size: 15px;
font-weight: 500;
border-radius: 40px;
width: 100%;
cursor: pointer;
transition: all 0.3s ease;
}
.primary-button:hover {
transform: scale(1.02);
background: #0071e3;
box-shadow: 0 0 25px rgba(41, 151, 255, 0.3);
}
.primary-button:active {
transform: scale(0.98);
opacity: 0.9;
}
.login-divider {
display: flex;
align-items: center;
margin: 20px 0;
color: var(--text-tertiary);
font-size: 12px;
font-weight: 400;
}
.login-divider::before,
.login-divider::after {
content: '';
flex: 1;
height: 1px;
background: var(--border-subtle);
}
.login-divider span {
padding: 0 14px;
}
.secondary-button {
background: rgba(255, 255, 255, 0.05);
color: var(--text-primary);
border: none;
padding: 14px 28px;
font-size: 15px;
font-weight: 400;
border-radius: 40px;
width: 100%;
cursor: pointer;
transition: all 0.3s ease;
}
.secondary-button:hover {
background: rgba(255, 255, 255, 0.1);
}
.secondary-button:active {
transform: scale(0.98);
}
#login-modal.hidden {
opacity: 0;
pointer-events: none;
}
#login-modal.hidden .login-card {
transform: scale(0.95);
}
@keyframes slideUpFade { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
@keyframes slideInRight { from { opacity: 0; transform: translateX(-10px); } to { opacity: 1; transform: translateX(0); } }
@media(min-width: 768px) {
#application-container, #overlay-panel { max-width: 800px; margin: 0 auto; border-left: 1px solid var(--border-subtle); border-right: 1px solid var(--border-subtle); }
#overlay-panel { left: 50%; transform: translateX(-50%) translateY(100%); max-width: 720px; border-radius: 18px 18px 0 0; top: 40px; height: calc(100% - 40px); border: 1px solid var(--border-subtle); border-bottom: none; overflow: hidden; }
#overlay-panel.visible { transform: translateX(-50%) translateY(0); }
}

/* Websets Manager Modal Styles */
.websets-modal {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(40px) saturate(180%);
    -webkit-backdrop-filter: blur(40px) saturate(180%);
    z-index: 3000;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.5s ease, visibility 0.5s ease;
}
.websets-modal.visible {
    opacity: 1;
    visibility: visible;
}
.websets-modal-content {
    background: var(--surface-glass-heavy);
    border: 1px solid var(--border-subtle);
    border-radius: 24px;
    padding: 24px;
    width: 90%;
    max-width: 800px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.7);
    animation: fadeIn 0.5s var(--ease-apple) forwards;
    display: flex;
    flex-direction: column;
    max-height: 90vh;
}
.websets-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}
.websets-header h2 {
    font-size: 18px;
    font-weight: 500;
    color: var(--text-primary);
    letter-spacing: -0.01em;
}
.websets-close-btn {
    background: rgba(255, 255, 255, 0.08);
    border: none;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-secondary);
    font-size: 24px;
    cursor: pointer;
    transition: all 0.2s ease;
    line-height: 1;
}
.websets-close-btn:hover {
    background: rgba(255, 255, 255, 0.15);
    color: var(--text-primary);
}
.websets-tabs {
    display: flex;
    gap: 8px;
    margin-bottom: 24px;
    border-bottom: 1px solid var(--border-subtle);
    padding-bottom: 12px;
}
.websets-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    font-size: 14px;
    font-weight: 500;
    padding: 8px 16px;
    border-radius: 20px;
    cursor: pointer;
    transition: all 0.3s ease;
}
.websets-tab.active {
    background: rgba(41, 151, 255, 0.1);
    color: var(--accent-blue);
}
.websets-tab:hover {
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-primary);
}
.websets-content {
    flex-grow: 1;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(255,255,255,0.2) transparent;
}
.websets-tab-panel {
    display: none;
}
.websets-tab-panel.active {
    display: block;
}
.websets-form {
    display: flex;
    flex-direction: column;
    gap: 16px;
}
.form-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.form-group label {
    font-size: 12px;
    font-weight: 500;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}
.form-group input[type="text"],
.form-group input[type="number"],
.form-group textarea {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 12px 16px;
    color: #fff;
    font-size: 14px;
    outline: none;
    transition: all 0.3s ease;
}
.form-group input[type="text"]:focus,
.form-group input[type="number"]:focus,
.form-group textarea:focus {
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 3px rgba(41, 151, 255, 0.15);
}
.websets-btn-primary {
    background: var(--accent-blue);
    color: #fff;
    border: none;
    padding: 12px 24px;
    font-size: 15px;
    font-weight: 500;
    border-radius: 30px;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 10px;
}
.websets-btn-primary:hover {
    background: #0071e3;
    box-shadow: 0 0 15px rgba(41, 151, 255, 0.3);
}
.websets-btn-primary:active {
    transform: scale(0.98);
}
.websets-list-container, .monitors-container {
    padding: 10px;
}
.webset-item, .monitor-item {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--border-subtle);
    border-radius: 12px;
    padding: 16px;
    margin-bottom: 10px;
    cursor: pointer;
    transition: all 0.2s ease;
}
.webset-item:hover, .monitor-item:hover {
    background: rgba(255, 255, 255, 0.06);
    border-color: rgba(255, 255, 255, 0.15);
}
.webset-item.active, .monitor-item.active {
    border-color: var(--accent-blue);
    box-shadow: 0 0 10px rgba(41, 151, 255, 0.2);
}
.webset-title, .monitor-title {
    font-size: 14px;
    font-weight: 400;
    color: var(--text-primary);
    margin-bottom: 6px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.webset-query, .monitor-details {
    font-size: 12px;
    color: var(--text-secondary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.monitor-details {
    font-size: 11px;
}
.websets-item-actions {
    display: flex;
    gap: 8px;
    margin-top: 10px;
}
.websets-action-btn {
    background: rgba(255, 255, 255, 0.05);
    border: none;
    color: var(--text-secondary);
    padding: 6px 12px;
    border-radius: 10px;
    font-size: 11px;
    cursor: pointer;
    transition: all 0.2s ease;
}
.websets-action-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-primary);
}
.websets-action-btn.delete {
    color: var(--danger);
}
.websets-action-btn.delete:hover {
    background: rgba(255, 69, 58, 0.1);
}

@keyframes fadeIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
</style>
</head>
